    items = []
    for sku, (qty, weight) in sku_map.items():
        for _ in range(qty):
            items.append((sku, weight))

    bins = first_fit_decreasing(items, max_parcel_grams)

    result: List[Dict[str, int]] = []
    for b in bins:
        parcel: Dict[str, int] = {}
        for sku, _ in b:
